data.code:
// Yesterday's Shopify orders, counted here so the AI never adds up numbers
const day = context.yesterday.result;
const orders = (context.orders.items || []).filter((order) => String(order.created_at || "").startsWith(day));
const sum = (list) => list.reduce((total, order) => total + Number(order.total_price || 0), 0);
const paid = orders.filter((order) => order.financial_status === "paid");
const pending = orders.filter((order) => order.financial_status === "pending");
const cancelled = orders.filter((order) => order.cancelled_at);
const unfulfilled = orders.filter((order) => !order.cancelled_at && !order.fulfillment_status);
const biggest = [...orders].sort((a, b) => Number(b.total_price || 0) - Number(a.total_price || 0)).slice(0, 5);
return {
  date: day,
  currency: orders[0] ? orders[0].currency : "",
  count: orders.length,
  total: sum(orders).toFixed(2),
  paidCount: paid.length,
  paidTotal: sum(paid).toFixed(2),
  pendingCount: pending.length,
  pendingTotal: sum(pending).toFixed(2),
  cancelledCount: cancelled.length,
  unfulfilledCount: unfulfilled.length,
  biggest: biggest.map((order) => order.name + ": " + order.total_price).join("\n") || "-",
};

